# Animation v2 · CV (chương mới) Vẽ và vector động
# Nguồn: Essentials Ch.41 (Canvas, DrawScope: line, rect, rotate, circle, gradient, arc, path, points, image, text);
# Android Animations by Tutorials Ch.2 (FavoriteButton: ValueAnimator.ofInt + updateLayoutParams, ObjectAnimator alpha, textSize) và Ch.10;
# quick-guide (drawBehind cho màu animate); "Animating vectors in Compose" (an-vectors); AnimatedVectorPainterResources.android.kt,
# Animator.kt, AnimatedImageVector.kt @296313a4 (animation-graphics); VectorPainter.kt @296313a4 (Composition(VectorApplier)).

def add(a):
    def B(ch, sec, n, field, vi, en=None):
        a('%s.sec.%s.b.%02d.%s' % (ch, sec, n, field), vi, vi if en is None else en)

    m = lambda k, vi, en=None: a('m.avd.' + k, vi, en)
    m('title', 'Vẽ động và vector động: giá trị được đọc ở đâu', 'Animated drawing and animated vectors: where the value is read')
    m('overview', 'Ba cách: một vòng tiến độ vẽ bằng `Canvas { drawArc(...) }` với góc quét từ `animateFloatAsState`; một AnimatedVectorDrawable chạy tới cuối (`atEnd = true`); và chạy ngược về đầu (`atEnd = false`). Theo dõi phần nào chạy lại mỗi frame và animation của vector đến từ đâu.', 'Three cases: a progress ring drawn with `Canvas { drawArc(...) }` whose sweep comes from `animateFloatAsState`; an AnimatedVectorDrawable played to the end (`atEnd = true`); and played back to the start (`atEnd = false`). Watch which part re-runs each frame and where the vector\'s animation comes from.')
    m('wrapup', 'Với Canvas, đọc giá trị animate BÊN TRONG lambda vẽ thì mỗi frame chỉ phase draw chạy lại. Với AnimatedVectorDrawable trong Compose, `rememberAnimatedVectorPainter` biến các animator của file XML thành con của một `updateTransition(atEnd)`; cây vector là một composition riêng, và khi `atEnd` đổi về false, mỗi spec được đảo ngược theo thời gian.', 'With Canvas, reading the animated value INSIDE the draw lambda means only the draw phase re-runs each frame. With an AnimatedVectorDrawable in Compose, `rememberAnimatedVectorPainter` turns the XML file\'s animators into children of an `updateTransition(atEnd)`; the vector tree is its own composition, and when `atEnd` goes back to false, each spec is reversed in time.')
    m('simp.1', 'Góc quét, góc xoay và số frame là minh họa; AVD giả định có một animator xoay 0 → 180 độ trong 300 ms.', 'Sweep angles, rotation angles and frame counts are illustrative; the AVD is assumed to have one rotation animator 0 → 180 degrees over 300 ms.')
    m('simp.2', 'Mô hình không đếm composition riêng của vector cho từng nhóm; chỉ cho thấy nó được chạy lại khi giá trị của transition đổi.', 'The model does not count the vector\'s own composition per group; it only shows that it re-runs when the transition\'s values change.')
    m('ctl.hint', 'So "Canvas" với "AVD tới cuối", rồi chạy "AVD về đầu".', 'Compare "Canvas" with "AVD to end", then run "AVD back to start".')
    m('ctl.which', 'Trường hợp', 'Case')
    for k, vi, en in [('canvas', 'Vẽ bằng Canvas + drawArc', 'Drawing with Canvas + drawArc'), ('forward', 'AVD tới cuối (atEnd = true)', 'AVD to end (atEnd = true)'), ('back', 'AVD về đầu (atEnd = false)', 'AVD back to start (atEnd = false)')]:
        m('ctl.which.' + k, vi, en)
    m('diagramTitle', 'State, animation, phần chạy lại, màn hình', 'State, animation, the part that re-runs, the screen')
    m('diagramDesc', 'State đổi đích; animation tính giá trị; giá trị được đọc ở lambda vẽ hoặc ở composition của vector; màn hình vẽ lại', 'The state changes the target; the animation computes the value; the value is read in the draw lambda or in the vector\'s composition; the screen redraws')
    for k, vi, en in [('state', 'State đích', 'Target state'), ('anim', 'Bộ animate', 'Animator'), ('reader', 'Nơi đọc giá trị', 'Where it is read'), ('screen', 'Màn hình', 'Screen')]:
        m('n.' + k, vi, en)
    for k, vi, en in [('comp', 'Recompose của composable chứa', 'Host composable recompositions'), ('vector', 'Lượt composition của vector', 'Vector composition passes'), ('draw', 'Lượt vẽ', 'Draw passes'), ('val', 'Giá trị (độ)', 'Value (degrees)')]:
        m('met.' + k, vi, en)
    for k, vi, en in [('val', 'Giá trị', 'Value'), ('spec', 'Spec đang dùng', 'Spec in use'), ('reader', 'Đọc ở', 'Read in')]:
        m('st.' + k, vi, en)
    S = [
        ('intro.canvas', 'Vòng tiến độ ở 0°', 'The progress ring at 0°', '`val sweep by animateFloatAsState(progress * 360f)`; trong `Canvas { drawArc(color, startAngle = -90f, sweepAngle = sweep, useCenter = false, style = Stroke(8.dp.toPx())) }`.', '`val sweep by animateFloatAsState(progress * 360f)`; inside `Canvas { drawArc(color, startAngle = -90f, sweepAngle = sweep, useCenter = false, style = Stroke(8.dp.toPx())) }`.'),
        ('intro.forward', 'AVD ở trạng thái đầu', 'The AVD at its start state', '`AnimatedImageVector.animatedVectorResource(R.drawable.ic_hourglass_animated)` và `rememberAnimatedVectorPainter(image, atEnd)`. Bên trong: `rememberVectorPainter { … updateTransition(atEnd) … }`.', '`AnimatedImageVector.animatedVectorResource(R.drawable.ic_hourglass_animated)` and `rememberAnimatedVectorPainter(image, atEnd)`. Inside: `rememberVectorPainter { … updateTransition(atEnd) … }`.'),
        ('intro.back', 'AVD đang ở trạng thái cuối', 'The AVD is at its end state', 'Cùng đoạn mã; lần này đổi `atEnd` từ true về false.', 'The same code; this time `atEnd` changes from true back to false.'),
        ('target.canvas', 'progress = 0.5: recompose MỘT lần', 'progress = 0.5: recompose ONCE', 'Composable chứa chạy lại để đưa đích mới (180°) cho `animateFloatAsState`.', 'The host composable runs again to give `animateFloatAsState` its new target (180°).'),
        ('target.avd', 'atEnd đổi: Transition có đích mới', 'atEnd changes: the Transition gets a new target', 'Composable chứa chạy lại một lần; `updateTransition(atEnd)` bắt đầu đi tới trạng thái mới.', 'The host composable runs once; `updateTransition(atEnd)` starts moving to the new state.'),
        ('frame.canvas', 'Frame {n}: góc quét {v}°, chỉ vẽ lại', 'Frame {n}: sweep {v}°, only redraw', '`sweep` được đọc trong lambda của Canvas (một `drawBehind`), nên chỉ phase draw chạy lại; composable chứa không recompose.', '`sweep` is read inside the Canvas lambda (a `drawBehind`), so only the draw phase re-runs; the host composable does not recompose.'),
        ('frame.forward', 'Frame {n}: xoay {v}°', 'Frame {n}: rotation {v}°', 'Animator `rotation` của file XML giờ là `transition.animateFloat` với keyframes. Giá trị được đọc trong composition RIÊNG của vector (VectorPainter dựng nó bằng `Composition(VectorApplier(...))`), rồi vẽ lại.', 'The XML file\'s `rotation` animator is now a `transition.animateFloat` with keyframes. The value is read in the vector\'s OWN composition (VectorPainter builds it with `Composition(VectorApplier(...))`), then redrawn.'),
        ('frame.back', 'Frame {n}: xoay {v}° (spec đảo ngược)', 'Frame {n}: rotation {v}° (reversed spec)', 'Khi đích là false, mã dùng `spec.reversed(overallDuration)`: cùng keyframes nhưng chạy ngược thời gian, nên chuyển động về đầu là ảnh gương của chuyển động tới cuối.', 'When the target is false, the code uses `spec.reversed(overallDuration)`: the same keyframes run backwards in time, so going back is the mirror image of going forward.'),
        ('done.canvas', 'Xong ở 180°', 'Done at 180°', 'Composable chứa recompose 1 lần, phase draw chạy mỗi frame.', 'The host recomposed once; the draw phase ran every frame.'),
        ('done.forward', 'Xong ở trạng thái cuối', 'Done at the end state', 'Transition tới đích; tổng thời lượng của AVD (`totalDuration`) là animator dài nhất, kể cả delay và repeat.', 'The Transition reached its target; the AVD\'s total duration (`totalDuration`) is its longest animator, including delays and repeats.'),
        ('done.back', 'Xong ở trạng thái đầu', 'Done at the start state', 'Về đầu bằng chính các animator đó, đảo ngược.', 'Back to the start using the same animators, reversed.'),
    ]
    for sid, tv, te, xv, xe in S:
        m('s.%s.title' % sid, tv, te); m('s.%s.explain' % sid, xv, xe); m('ev.' + sid, tv, te)
    for k, vi, en in [
        ('draw', 'Cầu nối X1: đọc trong lambda vẽ thì chỉ phase draw chạy lại (chương B7 của Runtime, chương C7). [[src:cp-phases]]', 'Bridge X1: reading in a draw lambda only re-runs the draw phase (Runtime chapter B7, chapter C7). [[src:cp-phases]]'),
        ('transition', 'Mã ở commit ghim: rememberAnimatedVectorPainter = rememberVectorPainter { updateTransition(atEnd) … target.animator.createVectorConfig(transition, totalDuration) }. [[src:an-avdpainter-src]]', 'Code at the pinned commit: rememberAnimatedVectorPainter = rememberVectorPainter { updateTransition(atEnd) … target.animator.createVectorConfig(transition, totalDuration) }. [[src:an-avdpainter-src]]'),
        ('vector', 'VectorPainter dựng nội dung vector bằng một Composition riêng với VectorApplier. [[src:ui-vectorpainter-src]]', 'VectorPainter builds the vector content with its own Composition using a VectorApplier. [[src:ui-vectorpainter-src]]'),
        ('reversed', 'Mã Animator.kt: `if (targetState) spec else spec.reversed(overallDuration)`. [[src:an-animator-src]]', 'Animator.kt code: `if (targetState) spec else spec.reversed(overallDuration)`. [[src:an-animator-src]]')]:
        m('co.' + k, vi, en)
    a('cap.avd', 'State bên trái đổi đích; animation tính giá trị; nút thứ ba là nơi giá trị được đọc (lambda vẽ hoặc composition của vector); màn hình bên phải vẽ lại.', 'The state on the left changes the target; the animation computes the value; the third node is where the value is read (the draw lambda or the vector\'s composition); the screen on the right redraws.')

    C = 'cv'
    a(C + '.title', 'Vẽ và vector động: Canvas, AnimatedVectorDrawable', 'Drawing and animated vectors: Canvas, AnimatedVectorDrawable')
    a(C + '.essence',
      'Vẽ bằng `Canvas`/`drawBehind` và đọc giá trị animate trong lambda vẽ: mỗi frame chỉ phase draw chạy lại.\nAnimatedVectorDrawable: `animatedVectorResource` + `rememberAnimatedVectorPainter(image, atEnd)`; bên trong, các animator XML thành con của `updateTransition(atEnd)`, đổi về false thì chạy ngược.\nTrong hệ View, animator cập nhật thuộc tính rồi View vẽ lại (hoặc đo lại nếu đổi layout params); Compose tách theo phase.',
      'Draw with `Canvas`/`drawBehind` and read the animated value inside the draw lambda: each frame only the draw phase re-runs.\nAnimatedVectorDrawable: `animatedVectorResource` + `rememberAnimatedVectorPainter(image, atEnd)`; inside, the XML animators become children of `updateTransition(atEnd)`, and going back to false plays them reversed.\nIn the View system, an animator updates a property and the View redraws (or re-measures if layout params change); Compose separates this by phase.')
    a(C + '.goal.g1', 'Đã đổi đích (progress hoặc atEnd)', 'Changed the target (progress or atEnd)')
    a(C + '.goal.g2', 'Đã chạy một trường hợp tới cuối', 'Ran one case to the end')
    a(C + '.sim.animation.avd', 'Vẽ động và AVD', 'Animated drawing and AVD')

    S = 'hook'
    a(C + '.sec.%s.title' % S, 'Đoán trước khi đọc', 'Predict before reading')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'predict', 'Một AnimatedVectorDrawable đồng hồ cát chạy tới cuối khi `atEnd = true`. Đổi `atEnd` về false thì sao: nhảy về hình đầu, chạy lại từ đầu, hay chạy NGƯỢC về?', 'An hourglass AnimatedVectorDrawable plays to the end when `atEnd = true`. What happens when `atEnd` goes back to false: jump to the first frame, play again from the start, or play BACKWARDS?')
    B(C, S, 1, 'ans', 'Chạy ngược. KDoc của `rememberAnimatedVectorPainter`: "thay đổi của atEnd được animate"; trong mã, khi đích là false mỗi spec được dùng ở dạng `spec.reversed(overallDuration)`. [[src:an-avdpainter-src]] [[src:an-animator-src]]', 'It plays backwards. The `rememberAnimatedVectorPainter` KDoc: "changes to atEnd are animated"; in the code, when the target is false each spec is used as `spec.reversed(overallDuration)`. [[src:an-avdpainter-src]] [[src:an-animator-src]]')

    S = 'views'
    a(C + '.sec.%s.title' % S, 'Trong hệ View: animator và custom view', 'In the View system: animators and custom views')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', '*Android Animations by Tutorials* Ch.2 làm hiệu ứng cho nút `FavoriteButton` (một `ExtendedFloatingActionButton` và một `CircularProgressIndicator`): `ValueAnimator.ofInt(rộng ban đầu, cao)` thu nút thành hình tròn, mỗi lần cập nhật gọi `updateLayoutParams { width = animatedValue }`; `ObjectAnimator.ofFloat(progressBar, "alpha", 0f, 1f)` cho thanh tiến độ hiện dần; và một animator cho cỡ chữ. Ch.10 làm lại đúng hiệu ứng đó bằng Compose. [[src:book-aat]]', '*Android Animations by Tutorials* Ch.2 animates a `FavoriteButton` (an `ExtendedFloatingActionButton` and a `CircularProgressIndicator`): `ValueAnimator.ofInt(initial width, height)` shrinks the button into a circle, calling `updateLayoutParams { width = animatedValue }` on each update; `ObjectAnimator.ofFloat(progressBar, "alpha", 0f, 1f)` fades the progress bar in; and an animator for the text size. Ch.10 rebuilds the same effect in Compose. [[src:book-aat]]')
    B(C, S, 2, 'p', 'Điểm cần thấy: trong hệ View, MỖI thuộc tính bạn animate quyết định khối lượng việc. Đổi layout params (như width) buộc đo và đặt lại; đổi alpha hay translation chỉ cần vẽ lại. Compose giữ nguyên ý đó nhưng nói bằng phase: đọc giá trị ở composition, layout hay draw (chương B7, C7). Với hình tự vẽ, chỗ tương ứng của `onDraw()` + `invalidate()` là lambda của `Canvas`/`drawBehind` đọc state. [[src:book-aat]] [[src:cp-phases]]', 'The point to notice: in the View system, EACH property you animate decides how much work happens. Changing layout params (like width) forces a re-measure and re-layout; changing alpha or translation only needs a redraw. Compose keeps the same idea but expresses it as phases: read the value in composition, layout or draw (chapters B7, C7). For custom drawing, the counterpart of `onDraw()` + `invalidate()` is a `Canvas`/`drawBehind` lambda that reads state. [[src:book-aat]] [[src:cp-phases]]')

    S = 'canvas'
    a(C + '.sec.%s.title' % S, 'Canvas và DrawScope', 'Canvas and DrawScope')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'p', 'Essentials Ch.41 đi qua các lệnh vẽ của `Canvas`: lấy `size` của vùng vẽ, `drawLine` (và nét đứt bằng `PathEffect.dashPathEffect`), `drawRect`, `rotate(degrees) { … }`, `drawCircle`/`drawOval`, gradient bằng `Brush`, `drawArc`, `drawPath`, `drawPoints`, `drawImage`, và chữ. Mọi lệnh chạy trong `DrawScope`, tức ở phase draw. Sách không animate Canvas; ghép với chương C1 rất trực tiếp: lấy một giá trị từ `animate*AsState` rồi đọc nó trong lambda vẽ. [[src:book-compose-ess]]', 'Essentials Ch.41 walks through `Canvas` drawing calls: getting the drawing area `size`, `drawLine` (and dashed lines with `PathEffect.dashPathEffect`), `drawRect`, `rotate(degrees) { … }`, `drawCircle`/`drawOval`, gradients with `Brush`, `drawArc`, `drawPath`, `drawPoints`, `drawImage`, and text. Every call runs inside a `DrawScope`, i.e. in the draw phase. The book does not animate the Canvas; combining it with chapter C1 is direct: take a value from `animate*AsState` and read it in the draw lambda. [[src:book-compose-ess]]')
    B(C, S, 2, 'kt', 'val sweep by animateFloatAsState(progress * 360f, label = "sweep")\nCanvas(Modifier.size(64.dp)) {\n    drawArc(\n        color = Teal,\n        startAngle = -90f,\n        sweepAngle = sweep,                 // đọc TRONG lambda vẽ: chỉ phase draw\n        useCenter = false,\n        style = Stroke(width = 8.dp.toPx(), cap = StrokeCap.Round)\n    )\n}', 'val sweep by animateFloatAsState(progress * 360f, label = "sweep")\nCanvas(Modifier.size(64.dp)) {\n    drawArc(\n        color = Teal,\n        startAngle = -90f,\n        sweepAngle = sweep,                 // read INSIDE the draw lambda: draw phase only\n        useCenter = false,\n        style = Stroke(width = 8.dp.toPx(), cap = StrokeCap.Round)\n    )\n}')
    B(C, S, 3, 'p', 'Cùng nguyên tắc cho màu nền: tài liệu "quick guide" khuyên animate màu bằng `Modifier.drawBehind { drawRect(animatedColor) }` thay vì `Modifier.background(animatedColor)`; `background` ổn cho màu đặt một lần, nhưng khi màu đổi theo thời gian nó có thể gây nhiều recomposition hơn cần thiết. [[src:an-quick]]', 'The same rule for background colours: the "quick guide" docs recommend animating a colour with `Modifier.drawBehind { drawRect(animatedColor) }` rather than `Modifier.background(animatedColor)`; `background` is fine for a one-shot colour, but when the colour changes over time it can cause more recompositions than necessary. [[src:an-quick]]')

    S = 'inside'
    a(C + '.sec.%s.title' % S, 'AnimatedVectorDrawable trong Compose, bên trong', 'AnimatedVectorDrawable in Compose, inside')
    a(C + '.sec.%s.badge' % S, 'impl')
    B(C, S, 1, 'p', 'Tài liệu nêu ba cách animate vector: định dạng AnimatedVectorDrawable; `ImageVector` kết hợp API animation của Compose; và thư viện bên thứ ba như Lottie. Với AVD: `AnimatedImageVector.animatedVectorResource(R.drawable.…)` rồi `rememberAnimatedVectorPainter(image, atEnd)`, đổi `atEnd` để chạy giữa trạng thái đầu và cuối. [[src:an-vectors]]', 'The docs list three ways to animate vectors: the AnimatedVectorDrawable format; `ImageVector` combined with Compose animation APIs; and third-party libraries such as Lottie. For an AVD: `AnimatedImageVector.animatedVectorResource(R.drawable.…)`, then `rememberAnimatedVectorPainter(image, atEnd)`, toggling `atEnd` to run between the start and end states. [[src:an-vectors]]')
    B(C, S, 2, 'p', 'Ở commit ghim (module `animation-graphics`): `AnimatedImageVector` giữ một `ImageVector` (phần `android:drawable` của `<animated-vector>`) và danh sách target (mỗi `<target>` = tên phần tử + một `Animator`); `totalDuration` là animator dài nhất, kể cả delay và repeat. `rememberAnimatedVectorPainter` gọi `rememberVectorPainter { … }` và bên trong tạo `updateTransition(atEnd)`; mỗi target gọi `animator.createVectorConfig(transition, totalDuration)`, nơi `ObjectAnimator`/`AnimatorSet`/`PropertyValuesHolder` của XML được đổi thành keyframes và `transition.animateFloat` (chương C3). Khi đích là false, spec được đảo ngược theo thời gian. [[src:an-avdpainter-src]] [[src:an-animator-src]] [[src:an-aiv-src]]', 'At the pinned commit (module `animation-graphics`): `AnimatedImageVector` holds an `ImageVector` (the `android:drawable` part of `<animated-vector>`) and a list of targets (each `<target>` = an element name + an `Animator`); `totalDuration` is the longest animator, including delays and repeats. `rememberAnimatedVectorPainter` calls `rememberVectorPainter { … }` and inside creates `updateTransition(atEnd)`; each target calls `animator.createVectorConfig(transition, totalDuration)`, where the XML\'s `ObjectAnimator`/`AnimatorSet`/`PropertyValuesHolder` become keyframes and `transition.animateFloat` (chapter C3). When the target is false, the spec is reversed in time. [[src:an-avdpainter-src]] [[src:an-animator-src]] [[src:an-aiv-src]]')
    B(C, S, 3, 'p', 'Còn `rememberVectorPainter` dựng cây vector bằng chính Compose: một `Composition` riêng với `VectorApplier`, nội dung là `RenderVectorGroup`. Vì vậy mỗi frame của transition, giá trị được đọc trong composition RIÊNG của vector rồi vẽ lại; composable gọi `Image(painter = …)` không phải recompose. Đây là một ví dụ thật của chương B6 (Applier) ngoài cây UI thường. [[src:ui-vectorpainter-src]]', '`rememberVectorPainter` in turn builds the vector tree with Compose itself: its own `Composition` with a `VectorApplier`, whose content is `RenderVectorGroup`. So on each frame of the transition, the value is read in the vector\'s OWN composition and then redrawn; the composable calling `Image(painter = …)` does not need to recompose. This is a real example of chapter B6 (Applier) outside the normal UI tree. [[src:ui-vectorpainter-src]]')
    B(C, S, 4, 'kt', 'val image = AnimatedImageVector.animatedVectorResource(R.drawable.ic_hourglass_animated)\nvar atEnd by remember { mutableStateOf(false) }\nImage(\n    painter = rememberAnimatedVectorPainter(image, atEnd),\n    contentDescription = "Timer",\n    modifier = Modifier.clickable { atEnd = !atEnd }\n)', 'val image = AnimatedImageVector.animatedVectorResource(R.drawable.ic_hourglass_animated)\nvar atEnd by remember { mutableStateOf(false) }\nImage(\n    painter = rememberAnimatedVectorPainter(image, atEnd),\n    contentDescription = "Timer",\n    modifier = Modifier.clickable { atEnd = !atEnd }\n)')
    B(C, S, 5, 'p', 'Mô phỏng ngay dưới so ba trường hợp: Canvas đọc giá trị trong lambda vẽ; AVD tới cuối; AVD về đầu với spec đảo ngược.', 'The simulation just below compares three cases: Canvas reading the value in the draw lambda; the AVD going to the end; the AVD going back with a reversed spec.')

    S = 'bugs'
    a(C + '.sec.%s.title' % S, 'Bug thường gặp', 'Common bugs')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'bug', 'Vòng tiến độ tự vẽ làm cả màn hình chi tiết recompose mỗi frame.', 'A custom-drawn progress ring makes the whole detail screen recompose every frame.')
    B(C, S, 1, 'cause', 'Giá trị animate được đọc ở thân composable (ví dụ truyền `sweep` làm tham số xuống `ProgressRing(sweep)`), không phải trong lambda vẽ.', 'The animated value is read in the composable body (for example passing `sweep` as a parameter down to `ProgressRing(sweep)`), not in the draw lambda.')
    B(C, S, 1, 'fix', 'Truyền lambda `sweep = { sweepState }` hoặc chính State, và chỉ đọc trong `Canvas { }`. [[src:cp-phases]] [[src:an-quick]]', 'Pass a lambda `sweep = { sweepState }` or the State itself, and read it only inside `Canvas { }`. [[src:cp-phases]] [[src:an-quick]]')
    B(C, S, 1, 'fixkt', '@Composable\nfun ProgressRing(sweep: () -> Float) {\n    Canvas(Modifier.size(64.dp)) { drawArc(Teal, -90f, sweep(), false, style = Stroke(8.dp.toPx())) }\n}', '@Composable\nfun ProgressRing(sweep: () -> Float) {\n    Canvas(Modifier.size(64.dp)) { drawArc(Teal, -90f, sweep(), false, style = Stroke(8.dp.toPx())) }\n}')
    B(C, S, 2, 'bug', 'Muốn AVD "chạy lại từ đầu" mỗi lần chạm nhưng lần chạm thứ hai lại chạy ngược.', 'You want the AVD to "play again from the start" on each tap, but the second tap plays it backwards.')
    B(C, S, 2, 'cause', '`rememberAnimatedVectorPainter` là một Transition hai trạng thái: đổi `atEnd` về false là đi ngược, không phải chạy lại.', '`rememberAnimatedVectorPainter` is a two-state Transition: setting `atEnd` back to false goes backwards, it does not replay.')
    B(C, S, 2, 'fix', 'Hiểu đúng mô hình hai trạng thái và thiết kế theo nó (tới/lui), hoặc tự điều khiển: dựng hình bằng `ImageVector` và animate các thuộc tính bằng `Animatable` (chương C6), nơi bạn có `snapTo(0f)` rồi `animateTo(1f)`. [[src:an-avdpainter-src]] [[src:an-vectors]]', 'Embrace the two-state model and design for it (forward/back), or take control yourself: build the image as an `ImageVector` and animate its properties with an `Animatable` (chapter C6), where you have `snapTo(0f)` then `animateTo(1f)`. [[src:an-avdpainter-src]] [[src:an-vectors]]')

    S = 'exercises'
    a(C + '.sec.%s.title' % S, 'Bài tập', 'Exercises')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'ex', 'Làm lại nút yêu thích của AAT Ch.2 bằng Compose: nút thu thành hình tròn, vòng tiến độ hiện dần và quay vô hạn bên trong.', 'Rebuild AAT Ch.2\'s favourite button in Compose: the button shrinks into a circle, a progress ring fades in and spins forever inside it.')
    B(C, S, 1, 'hint', 'Chiều rộng: animateDpAsState (đổi layout là đúng ý đồ). Alpha: đọc trong graphicsLayer. Vòng quay: rememberInfiniteTransition (chương IF) và đọc góc trong Canvas.', 'Width: animateDpAsState (changing layout is intended here). Alpha: read in graphicsLayer. Spin: rememberInfiniteTransition (chapter IF) and read the angle in the Canvas.')
    B(C, S, 1, 'sol', 'Ba animation, ba phase: chiều rộng đổi layout (chấp nhận vì nút thật sự đổi kích thước), alpha ở draw qua graphicsLayer, góc quay chỉ đọc trong Canvas nên chỉ vẽ lại. Khi lưu xong, ẩn vòng để InfiniteTransition rời composition.', 'Three animations, three phases: the width changes layout (acceptable, since the button really changes size), alpha at draw time via graphicsLayer, the rotation angle read only in the Canvas so it only redraws. When saving finishes, hide the ring so the InfiniteTransition leaves composition.')

    S = 'recall'
    a(C + '.sec.%s.title' % S, 'Tự trả lời', 'Answer it yourself')
    a(C + '.sec.%s.badge' % S, 'stable')
    B(C, S, 1, 'ask', 'rememberAnimatedVectorPainter dùng API animation nào bên trong?', 'Which animation API does rememberAnimatedVectorPainter use inside?')
    B(C, S, 1, 'ans', 'updateTransition(atEnd); mỗi animator XML thành transition.animateFloat (hoặc màu, path) với keyframes.', 'updateTransition(atEnd); each XML animator becomes a transition.animateFloat (or colour, path) with keyframes.')
    B(C, S, 2, 'ask', 'Đọc giá trị animate ở đâu để vòng tiến độ tự vẽ chỉ vẽ lại?', 'Where do you read the animated value so a custom progress ring only redraws?')
    B(C, S, 2, 'ans', 'Bên trong lambda của Canvas/drawBehind.', 'Inside the Canvas/drawBehind lambda.')
    for q, qv, qe, av, ae, wv, we in [
        ('q1', 'Đổi atEnd từ true về false thì AVD làm gì?', 'What does the AVD do when atEnd goes from true to false?', 'Chạy ngược về đầu.', 'Plays backwards to the start.', 'Spec được đảo ngược theo thời gian.', 'The spec is reversed in time.'),
        ('q2', 'Nội dung của một VectorPainter được dựng bằng gì?', 'What builds a VectorPainter\'s content?', 'Một Composition riêng với VectorApplier.', 'Its own Composition with a VectorApplier.', 'Cây vector là composable (RenderVectorGroup).', 'The vector tree is composable (RenderVectorGroup).'),
        ('q3', 'Animate màu nền: background hay drawBehind?', 'Animating a background colour: background or drawBehind?', 'drawBehind.', 'drawBehind.', 'Quick guide: drawBehind tránh recomposition thừa khi màu đổi theo thời gian.', 'The quick guide: drawBehind avoids extra recompositions when the colour changes over time.'),
        ('q4', 'Trong hệ View, animate width qua layout params thì View làm thêm việc gì so với animate alpha?', 'In the View system, what extra work does animating width via layout params cause compared with alpha?', 'Đo và đặt lại.', 'Re-measure and re-layout.', 'Đổi layout params buộc layout lại; alpha chỉ cần vẽ lại.', 'Changing layout params forces a new layout; alpha only needs a redraw.')]:
        a(C + '.quiz.%s.q' % q, qv, qe); a(C + '.quiz.%s.a' % q, av, ae); a(C + '.quiz.%s.why' % q, wv, we)
